'use strict';
const basicPageBeforeStaffPhoto=basicPage;
function safeStaffPhoto(value){return typeof value==='string'&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value)}
function staffInitial(name){return String(name||'S').trim().charAt(0).toUpperCase()||'S'}
function staffAvatarMarkup(staff){return safeStaffPhoto(staff.photo)?`<img class="staffPhotoThumb" src="${esc(staff.photo)}" alt="Photo of ${esc(staff.name)}">`:`<span class="staffPhotoPlaceholder" aria-hidden="true">${esc(staffInitial(staff.name))}</span>`}
basicPage=function(key){if(key!=='staff')return basicPageBeforeStaffPhoto(key);let rows=db.staff.filter(matches);if(filter)rows=rows.filter(x=>[x.status,x.category,x.type].includes(filter));return toolbar('Add Staff')+table(['Staff ID','Staff Name','Designation','Mobile Number','Specialization','Experience (Yrs)','Salary','Identity Details','Status','Actions'],rows.map(s=>[esc(s.id),`<div class="staffPhotoName">${staffAvatarMarkup(s)}<strong>${esc(s.name)}</strong></div>`,esc(s.designation),esc(s.mobile),esc(s.skills||'—'),esc(s.experience||0),s.salaryType==='Per Job'?`${esc(s.salary)}% (Per Job)`:money(s.salary)+` (${esc(s.salaryType)})`,[s.aadhaar?'Aadhaar saved':'',s.drivingLicense?'Driving licence saved':'',...['aadhaarDocument','drivingLicenseDocument'].map((k,i)=>{let f=null;try{f=JSON.parse(s[k])}catch{}return f&&safeAttachment(f)?(i?'Driving licence file: ':'Aadhaar file: ')+esc(f.name):''})].filter(Boolean).join(' · ')||'Not added',badge(s.status),actions(key,s.id)]))};
async function staffPhotoData(file){if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Choose a JPG, PNG or WebP photo.');if(file.size>5*1024*1024)throw Error('Choose a photo smaller than 5 MB.');if(typeof createImageBitmap!=='function')return await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read this photo.'));reader.readAsDataURL(file)});let image=await createImageBitmap(file),scale=Math.min(1,480/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close?.();let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.82));if(!blob)throw Error('Could not prepare this photo.');return await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read this photo.'));reader.readAsDataURL(blob)})}
const editRecordBeforeStaffPhoto=editRecord;
editRecord=function(key,id,initial={}){editRecordBeforeStaffPhoto(key,id,initial);if(key!=='staff')return;let form=$('#recordForm'),grid=form?.querySelector('.formgrid'),record=id?find('staff',id):initial;if(!grid)return;let field=document.createElement('div');field.className='field full staffPhotoField';let current=safeStaffPhoto(record?.photo)?record.photo:'';field.innerHTML=`<span>Staff Photo</span><div class="staffPhotoEditor"><div class="staffPhotoPreview">${current?`<img id="staffPhotoPreviewImage" src="${esc(current)}" alt="Staff photo preview">`:`<span id="staffPhotoPreviewInitial">${esc(staffInitial(record?.name))}</span>`}</div><div class="staffPhotoControls"><input type="hidden" name="photo" id="staffPhotoValue" value="${esc(current)}"><input type="file" id="staffPhotoUpload" accept="image/jpeg,image/png,image/webp" aria-label="Choose staff photo"><small>JPG, PNG or WebP. Photos are resized for this browser-local prototype.</small><button type="button" class="btn secondary small" id="removeStaffPhoto" ${current?'':'hidden'}>Remove Photo</button></div></div>`;grid.appendChild(field);let input=$('#staffPhotoUpload'),value=$('#staffPhotoValue'),preview=$('.staffPhotoPreview'),remove=$('#removeStaffPhoto');input.onchange=async()=>{let file=input.files?.[0];if(!file)return;input.disabled=true;try{let data=await staffPhotoData(file);value.value=data;preview.innerHTML=`<img id="staffPhotoPreviewImage" src="${esc(data)}" alt="Staff photo preview">`;remove.hidden=false}catch(error){toast(error.message)}finally{input.disabled=false;input.value=''}};remove.onclick=()=>{value.value='';preview.innerHTML=`<span id="staffPhotoPreviewInitial">${esc(staffInitial(form.elements.name?.value))}</span>`;remove.hidden=true;input.value=''}};
const renderBeforeStaffPhoto=render;
render=function(){renderBeforeStaffPhoto();if(page!=='staff')return;for(let image of $$('#content .staffPhotoThumb'))image.loading='lazy'};
render();


